<script setup>
import {ref,computed,watch,onMounted,onUnmounted} from 'vue'
import {api,post,put,remove} from '../../services/api'
import {definitions} from '../../config/resources'
import ImageCropUpload from '../../components/ImageCropUpload.vue'
import {Plus,Search,Pencil,Trash2,X,Save,RefreshCw,ChevronLeft,ChevronRight,Database,AlertCircle,CheckCircle2,SlidersHorizontal,ExternalLink} from 'lucide-vue-next'
const props=defineProps({resource:{type:String,required:true}})
const config=computed(()=>definitions[props.resource])
const rows=ref([]),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),search=ref(''),editing=ref(null),form=ref({}),showModal=ref(false),pendingDelete=ref(null),page=ref(1),size=10,modalError=ref(''),statusFilter=ref(''),developments=ref([])
const filtered=computed(()=>rows.value.filter(r=>(!statusFilter.value||String(r.status||'')===statusFilter.value)&&[...config.value.columns.map(k=>String(r[k]??'')),String(r.id)].join(' ').toLocaleLowerCase('es').includes(search.value.trim().toLocaleLowerCase('es'))))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/size)))
const visible=computed(()=>filtered.value.slice((page.value-1)*size,page.value*size))
watch([search,statusFilter,()=>props.resource],()=>{page.value=1})
function defaults(){return Object.fromEntries(config.value.fields.map(([key,,type,options])=>[key,type==='checkbox'?false:type==='select'?options[0]:'']))}
async function load(){loading.value=true;error.value='';try{const result=await api(`/admin/${props.resource}`);rows.value=result.data||[];if(props.resource==='lots'||props.resource==='leads'){try{const d=await api('/admin/developments');developments.value=d.data||[]}catch{developments.value=[]}}}catch(e){error.value=e.message}finally{loading.value=false}}
watch(()=>props.resource,()=>{search.value='';statusFilter.value='';success.value='';load()},{immediate:true})
function add(){editing.value=null;form.value=defaults();modalError.value='';showModal.value=true}
function edit(row){editing.value=row.id;form.value={...defaults(),...row};modalError.value='';showModal.value=true}
function close(){if(!saving.value)showModal.value=false}
async function save(){if(saving.value)return;saving.value=true;modalError.value='';success.value='';try{const values={...form.value};for(const key of ['id','created_at','updated_at'])delete values[key];for(const key in values)if(values[key]==='')values[key]=null;if(editing.value)await put(`/admin/${props.resource}/${editing.value}`,values);else await post(`/admin/${props.resource}`,values);showModal.value=false;success.value='Registro guardado correctamente.';await load()}catch(e){modalError.value=e.message}finally{saving.value=false}}
async function destroy(){if(!pendingDelete.value)return;const id=pendingDelete.value.id;pendingDelete.value=null;try{await remove(`/admin/${props.resource}/${id}`);success.value='Registro eliminado.';await load()}catch(e){error.value=e.message}}
const statuses={active:'Activo',inactive:'Inactivo',upcoming:'Próximamente',available:'Disponible',reserved:'Apartado',sold:'Vendido',new:'Nuevo',contacted:'Contactado',qualified:'Calificado',closed:'Cerrado'}
function display(value,col){if(typeof value==='boolean')return value?'Sí':'No';if(value==null||value==='')return '—';if(col==='price')return new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:2}).format(value);if(col==='created_at'){const d=new Date(value);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('es-MX')}return statuses[value]||value}
function waLink(phone){const digits=String(phone||'').replace(/\D/g,'');return digits?'https://wa.me/'+(digits.length===10?'52'+digits:digits):null}
function isStatus(col){return ['status','is_active','is_featured'].includes(col)}
function statusClass(value){return ['available','active','qualified',true].includes(value)?'is-positive':['sold','inactive','closed'].includes(value)?'is-neutral':['reserved','contacted','upcoming'].includes(value)?'is-warning':'is-info'}
function onKey(e){if(e.key==='Escape'&&!saving.value){showModal.value=false;pendingDelete.value=null}}
onMounted(()=>window.addEventListener('keydown',onKey));onUnmounted(()=>window.removeEventListener('keydown',onKey))
</script>
<template>
<div class="admin-page-head"><div><span class="admin-kicker">MÓDULOS / GESTIÓN</span><h1>{{config.title}}<span class="heading-dot">.</span></h1><p>{{config.description}}</p></div><button class="admin-primary" @click="add"><Plus :size="18"/> Agregar {{config.singular}}</button></div>
<div v-if="error" class="admin-alert error" role="alert"><AlertCircle :size="18"/> {{error}}</div><div v-if="success" class="admin-alert success" role="status"><CheckCircle2 :size="18"/> {{success}}</div>
<div class="admin-section-caption"><div><h2>Listado de {{config.title.toLowerCase()}}</h2><p>Consulta y actualiza tus registros desde aquí.</p></div><span class="admin-count-tag">{{filtered.length}} registros</span></div>
<div class="admin-panel admin-records-panel"><div class="admin-toolbar"><label class="admin-search"><Search :size="18"/><input v-model="search" :placeholder="`Buscar en ${config.title.toLowerCase()}…`" aria-label="Buscar registros"/></label><select v-if="['lots','leads','developments'].includes(props.resource)" v-model="statusFilter" class="v28-filter-select" aria-label="Filtrar estado"><option value="">Todos los estados</option><option v-for="[key,label] in Object.entries(statuses).filter(([key])=>props.resource==='lots'?['available','reserved','sold','inactive'].includes(key):props.resource==='developments'?['active','upcoming','inactive'].includes(key):['new','contacted','qualified','closed'].includes(key))" :key="key" :value="key">{{label}}</option></select><button class="admin-outline" :disabled="loading" @click="load"><RefreshCw :size="17" :class="{'spin-icon':loading}"/> Actualizar</button></div>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>REGISTRO</th><th v-for="column in config.columns" :key="column">{{config.fields.find(f=>f[0]===column)?.[1]||column}}</th><th class="actions-cell">ACCIONES</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td class="admin-record-id">#{{row.id}}</td><td v-for="column in config.columns" :key="column"><span v-if="isStatus(column)" class="admin-chip" :class="statusClass(row[column])"><span class="chip-dot"></span>{{display(row[column],column)}}</span><strong v-else-if="column===config.columns[0]" class="admin-td-title">{{display(row[column],column)}}</strong><span v-else>{{display(row[column],column)}}</span></td><td><div class="admin-row-actions"><a v-if="props.resource==='leads'&&waLink(row.phone)" class="v28-wa-btn" :href="waLink(row.phone)" title="Abrir WhatsApp" target="_blank" rel="noopener noreferrer">WhatsApp</a><button :aria-label="`Editar ${config.singular} #${row.id}`" title="Editar" @click="edit(row)"><Pencil :size="16"/></button><button :aria-label="`Eliminar ${config.singular} #${row.id}`" title="Eliminar" class="danger" @click="pendingDelete=row"><Trash2 :size="16"/></button></div></td></tr><tr v-if="!visible.length"><td :colspan="config.columns.length+2" class="admin-empty"><div class="admin-empty-icon"><Database :size="25"/></div><strong>{{loading?'Cargando registros…':search?'No encontramos coincidencias':'Todavía no hay registros'}}</strong><p>{{loading?'Consultando información del sistema.':search?'Prueba otro término de búsqueda.':`Agrega tu primer ${config.singular} para comenzar.`}}</p><button v-if="!loading&&!search" class="admin-outline" @click="add"><Plus :size="16"/> Crear registro</button></td></tr></tbody></table></div>
<div v-if="filtered.length>size" class="admin-pagination"><small>Mostrando {{(page-1)*size+1}}–{{Math.min(page*size,filtered.length)}} de {{filtered.length}}</small><div><button :disabled="page===1" aria-label="Anterior" @click="page--"><ChevronLeft :size="18"/></button><span>Página {{page}} de {{pages}}</span><button :disabled="page===pages" aria-label="Siguiente" @click="page++"><ChevronRight :size="18"/></button></div></div></div>
<div v-if="showModal" class="admin-modal-backdrop" @click.self="close"><div class="admin-modal" role="dialog" aria-modal="true" :aria-label="(editing?'Editar ':'Agregar ')+config.singular"><header><div><span class="admin-kicker">FORMULARIO / {{config.title.toUpperCase()}}</span><h2>{{editing?'Editar':'Agregar'}} {{config.singular}}</h2><p>Completa los datos y guarda los cambios.</p></div><button class="admin-icon-btn" type="button" aria-label="Cerrar" @click="close"><X :size="22"/></button></header><form @submit.prevent="save"><div class="admin-form-body"><div v-if="props.resource==='lots'" class="ad-form-guidance">Este inventario administra el estado de cada lote. Comprador, expediente y pagos se conectarán desde el módulo inmobiliario existente cuando se habilite su API.</div><div v-if="props.resource==='leads'" class="ad-form-guidance">Registro rápido: escribe nombre y teléfono. Después podrás contactar por WhatsApp desde la lista y actualizar el estado de seguimiento.</div><div v-if="config.fields.some(x=>x[2]==='image')" class="ad-form-guidance">Las imágenes se cargan desde este formulario, se recortan antes de subir y quedan vinculadas al registro. No necesitas entrar a una biblioteca.</div><p v-if="modalError" class="admin-alert error admin-form-error"><AlertCircle :size="16"/>{{modalError}}</p><label v-for="[key,label,type,options] in config.fields" :key="key" class="admin-field" :class="{'admin-checkbox':type==='checkbox'}"><template v-if="type==='checkbox'"><input v-model="form[key]" type="checkbox"/><span>{{label}}</span></template><template v-else><span>{{label}}</span><ImageCropUpload v-if="type==='image'" v-model="form[key]" :label="label" :ratio="props.resource==='testimonials'?1:16/9"/><textarea v-else-if="type==='textarea'" v-model="form[key]" rows="4" :placeholder="`Escribe ${label.toLowerCase()}…`"/><select v-else-if="type==='select'" v-model="form[key]"><option v-for="option in options" :key="option" :value="option">{{display(option)}}</option></select><select v-else-if="key==='development_id'&&developments.length" v-model="form[key]"><option value="">Selecciona un desarrollo</option><option v-for="d in developments" :key="d.id" :value="d.id">{{d.name}} (#{{d.id}})</option></select><input v-else v-model="form[key]" :type="type" :step="type==='number'?'any':undefined" :placeholder="label"/></template></label></div><footer><button type="button" class="admin-outline" @click="close">Cancelar</button><button class="admin-primary" type="submit" :disabled="saving"><Save :size="17"/> {{saving?'Guardando…':'Guardar cambios'}}</button></footer></form></div></div>
<div v-if="pendingDelete" class="admin-modal-backdrop" @click.self="pendingDelete=null"><div class="admin-confirm" role="alertdialog" aria-modal="true"><span class="confirm-danger-icon"><Trash2 :size="24"/></span><h2>¿Eliminar este registro?</h2><p>Se eliminará el {{config.singular}} #{{pendingDelete.id}}. Esta acción no se puede deshacer desde el panel.</p><div class="admin-confirm-actions"><button class="admin-outline" @click="pendingDelete=null">Cancelar</button><button class="admin-danger-button" @click="destroy">Sí, eliminar</button></div></div></div>
</template>
